(() => {
  let sniperLastUse = 0;
  let shotgunLastUse = 0;

  const SNIPER_COOLDOWN_MS = 2000;
  const SHOTGUN_COOLDOWN_MS = 1200;
  const PELLETS = 7;
  const SPREAD = 0.18;

  function lookDirection(yaw, pitch) {
    const cp = Math.cos(pitch);
    const sp = Math.sin(pitch);
    const cy = Math.cos(yaw);
    const sy = Math.sin(yaw);
    return {
      x: -sy * cp,
      y: sp,        // fixed vertical aim
      z: -cy * cp,
    };
  }

  return {
    items: {
      sniper: {
        onUse(game, api, event) {
          const now = Date.now();
          if (now - sniperLastUse < SNIPER_COOLDOWN_MS) return;
          sniperLastUse = now;

          api.projectiles.launch({
            speed: 80,
            lifetime: 10,
            damage: 10,
          });
        },
        onProjectileHit(game, api, event) {
          if (event.hit.type === 'block') {
            api.effects.particle(
              'break',
              event.hit.position.x,
              event.hit.position.y,
              event.hit.position.z
            );
          }
        }
      },

      shotgun: {
        onUse(game, api, event) {
          const now = Date.now();
          if (now - shotgunLastUse < SHOTGUN_COOLDOWN_MS) return;
          shotgunLastUse = now;

          const base = lookDirection(event.player.yaw, event.player.pitch);

          for (let i = 0; i < PELLETS; i++) {
            api.projectiles.launch({
              speed: 12 + Math.random() * 6,
              lifetime: 2.5,
              damage: 2,
              direction: {
                x: base.x + (Math.random() - 0.5) * SPREAD * 2,
                y: base.y + (Math.random() - 0.5) * SPREAD * 2,
                z: base.z + (Math.random() - 0.5) * SPREAD * 2,
              },
            });
          }
        },
        onProjectileHit(game, api, event) {
          if (event.hit.type === 'block') {
            api.effects.particle(
              'break',
              event.hit.position.x,
              event.hit.position.y,
              event.hit.position.z
            );
          }
        }
      },

      ammo: {
        onBlockUse(game, api, event) {
          api.effects.playSound('pickup');
        }
      }
    }
  };
})()
